"use server";

import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { logEvent } from "@/lib/log";

type ActionState = { error?: string };

const schema = z.object({
  id: z.string().optional(),
  author: z.string().min(1, "Author name is required.").max(80),
  role: z.string().max(120).optional(),
  quote: z.string().min(1, "Quote is required.").max(1000),
  avatarEmoji: z.string().max(8).optional(),
  rating: z.coerce.number().int().min(1).max(5).default(5),
  sortOrder: z.coerce.number().int().min(0).max(9999).default(0),
  published: z.boolean(),
});

/** Create or update a testimonial. Wired to a <form> via useActionState. */
export async function saveTestimonial(
  _prev: ActionState,
  formData: FormData,
): Promise<ActionState> {
  await requireArea("platform");

  const parsed = schema.safeParse({
    id: (formData.get("id") as string) || undefined,
    author: formData.get("author"),
    role: (formData.get("role") as string) || undefined,
    quote: formData.get("quote"),
    avatarEmoji: (formData.get("avatarEmoji") as string) || undefined,
    rating: formData.get("rating") ?? 5,
    sortOrder: formData.get("sortOrder") ?? 0,
    published: formData.get("published") === "on" || formData.get("published") === "true",
  });

  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid testimonial." };
  }

  const { id, role, avatarEmoji, ...rest } = parsed.data;
  const data = {
    ...rest,
    role: role || null,
    avatarEmoji: avatarEmoji || null,
  };

  try {
    if (id) {
      const existing = await db.testimonial.findUnique({ where: { id } });
      if (!existing) return { error: "Testimonial not found." };
      await db.testimonial.update({ where: { id }, data });
    } else {
      await db.testimonial.create({ data });
    }
  } catch (err) {
    await logEvent("error", "testimonial.save", { message: String(err), author: data.author });
    return { error: "Could not save the testimonial. Please try again." };
  }

  revalidatePath("/admin/testimonials");
  revalidatePath("/");
  redirect("/admin/testimonials");
}

/** Flip a testimonial between hidden and published. */
export async function toggleTestimonialPublish(id: string): Promise<ActionState> {
  await requireArea("platform");
  const t = await db.testimonial.findUnique({ where: { id } });
  if (!t) return { error: "Testimonial not found." };

  await db.testimonial.update({ where: { id }, data: { published: !t.published } });

  revalidatePath("/admin/testimonials");
  revalidatePath("/");
  return {};
}

/** Permanently delete a testimonial. */
export async function deleteTestimonial(id: string): Promise<ActionState> {
  await requireArea("platform");
  const t = await db.testimonial.findUnique({ where: { id } });
  if (!t) return { error: "Testimonial not found." };

  await db.testimonial.delete({ where: { id } });

  revalidatePath("/admin/testimonials");
  revalidatePath("/");
  return {};
}

