import { useActionState, useState, useTransition } from "react";
import {
  saveTestimonial,
  toggleTestimonialPublish,
  deleteTestimonial,
} from "@/lib/actions-testimonials";

type Testimonial = {
  id: string;
  author: string;
  role: string | null;
  quote: string;
  avatarEmoji: string | null;
  rating: number;
  published: boolean;
  sortOrder: number;
};

/** Create / edit form. Pass a `testimonial` to edit, omit to create. */
export function TestimonialEditor({ testimonial }: { testimonial?: Testimonial }) {
  const [state, action, pending] = useActionState(saveTestimonial, {});
  const editing = Boolean(testimonial?.id);

  return (
    <form action={action} className="space-y-4">
      {testimonial?.id && <input type="hidden" name="id" value={testimonial.id} />}

      {state?.error && (
        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}

      <div className="grid gap-4 sm:grid-cols-2">
        <div>
          <label className="label">Author</label>
          <input
            className="input"
            name="author"
            defaultValue={testimonial?.author}
            required
            maxLength={80}
            placeholder="Jane Doe"
          />
        </div>
        <div>
          <label className="label">Role / company (optional)</label>
          <input
            className="input"
            name="role"
            defaultValue={testimonial?.role ?? ""}
            maxLength={120}
            placeholder="Founder, Acme Studios"
          />
        </div>
        <div>
          <label className="label">Avatar emoji (optional)</label>
          <input
            className="input"
            name="avatarEmoji"
            defaultValue={testimonial?.avatarEmoji ?? ""}
            maxLength={8}
            placeholder="🧑‍💻"
          />
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="label">Rating (1–5)</label>
            <input
              className="input"
              name="rating"
              type="number"
              min={1}
              max={5}
              defaultValue={testimonial?.rating ?? 5}
            />
          </div>
          <div>
            <label className="label">Sort order</label>
            <input
              className="input"
              name="sortOrder"
              type="number"
              min={0}
              max={9999}
              defaultValue={testimonial?.sortOrder ?? 0}
            />
          </div>
        </div>
      </div>

      <div>
        <label className="label">Quote</label>
        <textarea
          className="input min-h-[120px]"
          name="quote"
          defaultValue={testimonial?.quote}
          required
          maxLength={1000}
          rows={4}
          placeholder="Nxeon had my game server live in under two minutes — full root, and it just worked."
        />
      </div>

      <div className="flex flex-wrap items-center justify-between gap-3 border-t border-white/[0.06] pt-4">
        <label className="flex items-center gap-2 text-sm text-slate-300">
          <input
            type="checkbox"
            name="published"
            defaultChecked={testimonial?.published ?? false}
