/** Per-row publish toggle + delete for the testimonials table. */
export function TestimonialRowActions({
  id,
  published,
}: {
  id: string;
  published: boolean;
}) {
  const [pending, start] = useTransition();
  const [confirming, setConfirming] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  return (
    <div className="flex items-center justify-end gap-2">
      {err && <span className="text-xs text-red-400">{err}</span>}

      <Link href={`/admin/testimonials?edit=${id}`} className="btn-secondary px-3 py-1.5 text-xs">
        Edit
      </Link>

      <button
        className="btn-secondary px-3 py-1.5 text-xs"
        disabled={pending}
        onClick={() =>
          start(async () => {
            setErr(null);
            const res = await toggleTestimonialPublish(id);
            if (res.error) setErr(res.error);
          })
        }
      >
        {published ? "Hide" : "Publish"}
      </button>

      {confirming ? (
        <>
          <button
            className="btn-danger px-3 py-1.5 text-xs"
            disabled={pending}
            onClick={() =>
              start(async () => {
                setErr(null);
                const res = await deleteTestimonial(id);
                if (res.error) {
                  setErr(res.error);
                  setConfirming(false);
                }
              })
            }
          >
            {pending ? "Deleting…" : "Confirm"}
          </button>
          <button
            className="btn-ghost px-2 py-1.5 text-xs"
            disabled={pending}
            onClick={() => setConfirming(false)}
          >
            Cancel
          </button>
        </>
      ) : (
        <button className="btn-danger px-3 py-1.5 text-xs" onClick={() => setConfirming(true)}>
          Delete
        </button>
      )}
    </div>
  );
}

